const RELEASE = __RELEASE__;
const ASSETS = __ASSETS__;
const PREFIX = 'lexicon-shell-';
const CACHE = PREFIX + RELEASE;
const root = new URL('./', self.location.href);
const assetPaths = new Set(ASSETS.map(asset => new URL(asset.path, root).pathname));

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    // Stage atomically: a partial/old CDN response never becomes a ready update.
    const responses = await Promise.all(ASSETS.map(async asset => {
      const url = new URL(asset.path, root);
      // Pages may redirect index.html to '/'. Fetch canonical HTML directly;
      // retain the explicit index.html cache key and verify the same byte hash.
      const response = await fetch(asset.path === 'index.html' ? root : url, { cache: 'no-store', credentials: 'omit' });
      if (!response.ok || response.redirected) throw new Error('App shell unavailable');
      const hash = Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', await response.clone().arrayBuffer())))
        .map(byte => byte.toString(16).padStart(2, '0')).join('');
      if (hash !== asset.sha256) throw new Error('App shell version mismatch');
      return [url.href, response];
    }));
    const cache = await caches.open(CACHE);
    await Promise.all(responses.map(([url, response]) => cache.put(url, response)));
    // No skipWaiting here: only a user's Update click activates a waiting update.
  })());
});

self.addEventListener('message', event => {
  if (event.data?.type === 'GET_VERSION') event.ports[0]?.postMessage({ version: RELEASE });
  if (event.data?.type === 'SKIP_WAITING') event.waitUntil(self.skipWaiting());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if ((key.startsWith(PREFIX) && key !== CACHE) || key.startsWith('lexicon-pdf-ui-')) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', event => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== root.origin || request.headers.has('Authorization') ||
      request.headers.has('Range')) return;
  const navigation = request.mode === 'navigate' && (url.pathname === root.pathname || url.pathname === root.pathname + 'index.html');
  // Nothing outside the explicit public app-shell allowlist is stored or served.
  if (!navigation && (!assetPaths.has(url.pathname) || url.search)) return;
  const key = navigation ? new URL('index.html', root).href : url.href;
  event.respondWith((async () => {
    const cached = await (await caches.open(CACHE)).match(key);
    if (cached) return cached;
    // Do not silently mix a different release into this app shell.
    return new Response('App shell unavailable. Reconnect and reopen LEXICON.', { status: 503 });
  })());
});
